ports = [22, 80, 443]
for p in ports:
    print(f"DEBUG: checking port {p}")
    if p == 80:
        print("Found HTTP!")
        break

def scan_ports(port_list):
    assert len(port_list) > 0, "No ports to scan"
    for port in port_list:
        print(f"Scanning {port}")

scan_ports([])  # Will raise AssertionError
